#!/usr/bin/env bun
/**
 * Bundle `mod-projection.ts` into `plugin/hooks/projection.js`, which the mod imports. The output is
 * committed, because the plugin is installed from the repository as it stands, without a build.
 * `tests/mod-projection.test.ts` fails when it is stale.
 */

import { join } from 'node:path';

export const PROJECTION_FILE = join(import.meta.dir, '../plugin/hooks/projection.js');

const BANNER =
  '// Generated by scripts/build-mod-projection.ts from structured-context/browser and structured-context-map-views.\n' +
  '// Do not edit: run `bun run build:mod-projection`.\n';

export async function buildModProjection(): Promise<string> {
  const result = await Bun.build({
    entrypoints: [join(import.meta.dir, 'mod-projection.ts')],
    target: 'browser',
    format: 'esm',
  });
  if (!result.success) throw new AggregateError(result.logs, 'bundling the mod projection failed');
  // Bun names each input by its path from the build's root; keep them stable wherever the repo is
  const code = (await result.outputs[0]!.text()).replace(/^\/\/ .*(node_modules|src)\//gm, '// $1/');
  return BANNER + code;
}

if (import.meta.main) {
  await Bun.write(PROJECTION_FILE, await buildModProjection());
}
